generated_sql:
SELECT c.name AS card_name, c.promoTypes AS promotion_type
FROM cards c
WHERE LOWER(c.name) = 'duress';

SELECT CAST(SUM(CASE WHEN LOWER(language) = 'portuguese (brazil)' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS percentage
FROM set_translations
WHERE LOWER(language) LIKE '%portuguese%';

SELECT SUM(p.Score) AS total_score
FROM posts p
WHERE strftime('%Y-%m-%d', p.CreaionDate) = '2010-07-19';

SELECT CAST(SUM(CASE WHEN LOWER(g.gender) = 'male' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN LOWER(g.gender) IN ('female', 'male') THEN 1 ELSE 0 END) AS ratio
FROM superhero s
JOIN gender g ON s.gender_id = g.id;

SELECT superhero_name 
FROM superhero 
WHERE LOWER(full_name) = LOWER('Charles Chandler');

SELECT c.name AS circuit_name, c.location, c.lat, c.lng
FROM circuits c
WHERE LOWER(c.name) LIKE '%malaysian%' OR LOWER(c.location) LIKE '%malaysia%';

SELECT CAST(COUNT(*) AS REAL) / 10.0 AS avg_races_per_year
FROM (
    SELECT COUNT(*) AS race_count
    FROM races
    WHERE year >= 2000 AND year < 2010
);

SELECT CAST(SUM(CASE WHEN LOWER(preferred_foot) = 'left' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS percentage
FROM Player_Attributes
WHERE strftime('%Y', date) IN ('1987', '1988', '1989', '1990', '1991', '1992');

SELECT CAST(strftime('%s', MIN(`Examination Date`)) - strftime('%s', `First Date`) AS INTEGER) / 86400.0 AS days_diff
FROM Examination
WHERE ID = 821298;

SELECT CAST(SUM(CASE WHEN LOWER(SEX) = 'f' AND UA > 0 THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS percentage
FROM Laboratory
JOIN Patient ON Laboratory.ID = Patient.ID;

SELECT COUNT(DISTINCT city) AS city_count
FROM zip_code
WHERE LOWER(county) = 'orange' AND LOWER(state) = 'virginia';

SELECT first_name || ' ' || last_name AS full_name, email
FROM member
WHERE position = 'Secretary';

SELECT CAST(SUM(CASE WHEN Segment = 'LAM' AND Consumption > 46.73 THEN 1 ELSE 0 END) AS REAL) * 100 / SUM(CASE WHEN Segment = 'LAM' THEN 1 ELSE 0 END) AS percent_consumed_more_than_46_73
FROM yearmonth
JOIN customers ON yearmonth.CustomerID = customers.CustomerID;

SELECT CAST(SUM(CASE WHEN Consumption > 528.3 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage
FROM yearmonth
WHERE strftime('%Y-%m', Date) = '2012-02';
